SELECT COUNT(*) AS total_admissions, SUM(CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 90 AND 100 THEN 1 ELSE 0 END) AS male_patients, SUM(CASE WHEN d.diagnosis_code = 'ACS' THEN 1 ELSE 0 END) AS admissions_with_acs, SUM(CASE WHEN l.itemid = 707971 AND l.value IN ('Normal', 'Borderline', 'Elevated') THEN 1 ELSE 0 END) AS troponin_t_normal_or_borderline_or_elevated, AVG(i.length_of_stay) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN labevents l ON a.hadm_id = l.hadm_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.anchor_age = 95;